<!-- 1.7 Symmetry and every tensor (content/chapters/01-crystal/manuscript.md Sec. 7; FIG-01-06 Neumann machine, FIG-01-07
     Which face is +z). Group action: src/lib/physics/symmetry.ts; figure modules nm.ts and pz.ts. -->
<script lang="ts">
  import { onMount } from "svelte";
  import type { PageData } from "./$types";
  import CrystalSection from "$lib/figures/crystal/CrystalSection.svelte";
  import ModeVariant from "$lib/components/ModeVariant.svelte";
  import Badge from "$lib/components/Badge.svelte";
  import { mountNeumann } from "$lib/figures/crystal/nm";
  import { mountPlusZ } from "$lib/figures/crystal/pz";
  import { usePops } from "$lib/content/pops";
  import "$lib/figures/crystal/nm.css";
  import "$lib/figures/crystal/pz.css";

  let { data }: { data: PageData } = $props();
  const N = $derived(data.nm);
  const Z = $derived(data.pz);
  const C = $derived(data.counts);
  const D = $derived(data.nmInit);

  const KT = [["pyro", "pyro", "Pyroelectric p (rank 1)"], ["eps", "ε", "Permittivity ε (rank 2)"], ["d", "d", "Piezoelectric d (rank 3)"], ["r", "r", "Electro-optic r (rank 3)"], ["c", "c", "Elastic stiffness c (rank 4)"], ["s", "s", "Elastic compliance s (rank 4)"], ["p", "photoel.", "Photoelastic p (rank 4)"]] as const;
  const KV = [["pyro", "Pyroelectric p"], ["eps", "Permittivity ε"], ["d", "Piezo d"], ["r", "Electro-optic r"], ["c", "Stiffness c"], ["s", "Compliance s"], ["p", "Photoelastic p"]] as const;
  const OT = [["C3", "C3", "Threefold rotation about z (C3; C3² follows by closure)"], ["myz", "m yz", "Mirror yz, normal along x"], ["mp60", "m +60°", "Mirror with normal at +60° from x"], ["mm60", "m −60°", "Mirror with normal at −60° from x"]] as const;
  const OV = [["C3", "Threefold C3"], ["myz", "Mirror yz"], ["mp60", "Mirror +60°"], ["mm60", "Mirror −60°"]] as const;
  const FT = [["0", "0"], ["x", "x"], ["y", "y"], ["z", "z"]] as const;
  const PZT = [["sq", "1 compress along c", "compress"], ["cool", "2 cool", "cool"], ["etch", "3 etch", "etch"]] as const;
  const PZV = [["sq", "Compress along c", "Squeeze"], ["cool", "Cool on a Peltier stage", "Cool"], ["etch", "Etch", "Etch"]] as const;

  usePops({
    "d:nm": { h: "Neumann machine: method", body: "A generic tensor with the property's index symmetry (21 for c and s, 36 for the photoelastic p, 18 for d and r) is averaged over every element of the group generated by the selected operations (Reynolds operator, on the full tensor), then contracted to Voigt form; the invariant subspace is reduced to row echelon form with the conventional independents first, and every other component is classed zero, equal, minus, multiple, or combination (tolerance 10<sup>&minus;12</sup>). Frame IEEE 176: x normal to the yz mirror, z along c. With a field, the group is the subgroup of elements g with gE = E.", badges: [["d", "derived"]] },
    "d:voigt": { h: "Voigt contraction factors", body: "11&rarr;1, 22&rarr;2, 33&rarr;3, 23&rarr;4, 13&rarr;5, 12&rarr;6. Piezoelectric d<sub>iJ</sub> = f<sub>J</sub> d<sub>ijk</sub>, compliance s<sub>IJ</sub> = f<sub>I</sub> f<sub>J</sub> s<sub>ijkl</sub>, with f = 1 for J = 1, 2, 3 and 2 for J = 4, 5, 6 (engineering shear strain); c<sub>IJ</sub> = c<sub>ijkl</sub>, r<sub>Ik</sub> = r<sub>ijk</sub> and photoelastic p<sub>IJ</sub> = p<sub>ijkl</sub> carry no factor. Example: d<sub>16</sub> = 2d<sub>xxy</sub> and 3m forces d<sub>xxy</sub> = &minus;d<sub>yyy</sub>, so d<sub>16</sub> = &minus;2d<sub>22</sub>.", badges: [["d", "derived"]] },
    "d:forms": { h: "Computed count", body: "Independent components / generic components under all six operations of 3m, from the same group action as the Neumann machine, evaluated at prerender.", badges: [["d", "derived"]] },
    "d:signs": { h: "Sign changes under 180&deg; rotations", body: "A 180&deg; rotation about z (x &rarr; &minus;x, y &rarr; &minus;y) reverses every tensor component with an odd number of x and y indices: d<sub>22</sub>, r<sub>22</sub>, c<sub>14</sub>, s<sub>14</sub>, p<sub>14</sub>, p<sub>41</sub>. A 180&deg; rotation about x (y &rarr; &minus;y, z &rarr; &minus;z) reverses every component with an odd number of y and z indices; in 3m that is every allowed component of the odd-rank tensors (p, d, r, &chi;<sup>(2)</sup>) and no component of c or of the photoelastic p. Fixing +z by d<sub>33</sub> &gt; 0 and +y by d<sub>22</sub> &gt; 0 removes both freedoms, which fixes the sign of c<sub>14</sub>.", badges: [["d", "derived"]], },
    "d:curie": { h: "Residual group under a field", body: () => "Elements of 3m that leave E unchanged: E &parallel; z keeps all six (3m); E &parallel; y keeps the identity and the yz mirror (m); E &parallel; x keeps only the identity (1). Computed with stabilizer() over the six matrices of 3m: " + `z &rarr; ${data.stab.z}, y &rarr; ${data.stab.y}, x &rarr; ${data.stab.x}.`, badges: [["d", "derived"]] },
    "d:rform": { h: "Induced impermeability", body: "&Delta;B<sub>I</sub> = r<sub>Ij</sub>E<sub>j</sub> with the 3m form r<sub>12</sub> = &minus;r<sub>22</sub>, r<sub>61</sub> = &minus;r<sub>22</sub>, r<sub>42</sub> = r<sub>51</sub>, r<sub>23</sub> = r<sub>13</sub>. E<sub>x</sub>: &Delta;B<sub>5</sub> = r<sub>51</sub>E<sub>x</sub>, &Delta;B<sub>6</sub> = &minus;r<sub>22</sub>E<sub>x</sub>. E<sub>y</sub>: &Delta;B<sub>1</sub> = &minus;r<sub>22</sub>E<sub>y</sub>, &Delta;B<sub>2</sub> = r<sub>22</sub>E<sub>y</sub>, &Delta;B<sub>4</sub> = r<sub>51</sub>E<sub>y</sub>. An xy term with equal xx and yy parts puts the in-plane principal axes at 45&deg;.", badges: [["d", "derived"]] },
    "d:pz": { h: "Signs of the three tests", body: "Compression along c: stress T<sub>3</sub> &lt; 0 and d<sub>33</sub> &gt; 0 (IEEE 176) give &Delta;P<sub>3</sub> = d<sub>33</sub>T<sub>3</sub> &lt; 0, so the +z face loses positive bound charge. Cooling: p<sub>3</sub> &lt; 0 and &Delta;T &lt; 0 give &Delta;P<sub>3</sub> = p<sub>3</sub>&Delta;T &gt; 0, so the +z face gains it. Signs only; no magnitudes are drawn.", badges: [["d", "derived"]] },
  });

  let nmT: HTMLElement, nmV: HTMLElement, pzT: HTMLElement, pzV: HTMLElement;
  onMount(() => {
    const offs = [mountNeumann(nmT, nmV), mountPlusZ(pzT, pzV)];
    return () => offs.forEach((f) => f());
  });
</script>

<CrystalSection slug="symmetry" pops={data.pops} refs={data.refs}
  depth={[{ id: "l1", label: "L1 Neumann's principle" }, { id: "l2", label: "L2 Axes and allowed forms" }, { id: "l3", label: "L3 Signs and broken symmetry" }]}>

  <section class="lay" id="l1" data-pair="l1" data-spine="L1 Neumann's principle">
    <div class="sh"><h2 class="biref">L1 Neumann's principle</h2><span class="meta">Weis & Gaylord 1985 p. 198; point group 3m, IEEE 176 frame</span></div>
    <div class="body">
      <p class="tx">A crystal property can have no less symmetry than the crystal. This is <span class="term" data-pop="g:neumann-s-principle">Neumann's principle</span>, stated in 1833 <Badge code="P" pop="r:weis1985|p. 198" />. For LiNbO<sub>3</sub> (<span class="term" data-pop="g:point-group-3m">point group 3m</span>) it means every response must look the same after a 120&deg; turn about <i>c</i> and after reflection in any of the three <span class="term" data-pop="g:mirror-plane">mirror planes</span>. Most conceivable coefficients fail that test and are exactly zero; the survivors are tied together in fixed ratios.</p>
      <p class="tx">Consequences you can see: the crystal has one <span class="term" data-pop="g:optic-axis">optic axis</span>, along <i>c</i>, so light travelling along <i>c</i> sees one index whatever its polarization; along any other direction it splits in two (<a class="lk" href="/light/">02 Light</a>). Heating or cooling puts charge only on the <i>c</i> faces. Compression along any axis never charges the <i>x</i> faces, which are perpendicular to a mirror plane <Badge code="P" pop="r:weis1985|p. 195" />.</p>

      <ModeVariant>
        {#snippet tech()}
        <figure class="panel nm-t" data-pair="nm" bind:this={nmT}>
          <div class="ph"><span>Neumann machine: <output class="cx-ro nm-kind">{N.kind}</output></span><output class="cx-ro nm-hdr">{N.hdr}</output></div>
          <div class="nm-ctl">
            <span class="lbl">property</span>
            <div class="seg" role="group" aria-label="Property tensor">{#each KT as [k, l, t] (k)}<button type="button" data-nm-k={k} title={t} class:on={D.kind === k} aria-pressed={D.kind === k}>{l}</button>{/each}</div>
            <span class="lbl">generators</span>
            <div class="nm-ops">
              <div class="seg" role="group" aria-label="Symmetry operations">{#each OT as [k, l, t] (k)}<button type="button" data-nm-op={k} title={t} class:on={D.ops[k]} aria-pressed={D.ops[k]}>{l}</button>{/each}</div>
              <div class="seg" role="group" aria-label="Operation presets"><button type="button" data-nm-pre="none" title="All generators off: group 1">none</button><button type="button" data-nm-pre="all" title="All generators on: group 3m">all 3m</button></div>
            </div>
            <span class="lbl">field</span>
            <div class="seg" role="group" aria-label="Applied field direction">{#each FT as [k, l] (k)}<button type="button" data-nm-f={k} class:on={D.field === k} aria-pressed={D.field === k}>{#if k === "0"}E = 0{:else}E<sub>{l}</sub>{/if}</button>{/each}</div>
            <span class="lbl">group</span>
            <div class="nm-el" aria-live="polite">{@html N.el}</div>
          </div>
          <div class="nm-body">
            <div class="cx-tw nm-mxw"><div class="nm-mx" data-sweep data-nm-hover role="img" aria-label="Voigt matrix of the selected property under the selected group">{@html N.mx}</div></div>
            <div class="nm-side">
              <div class="nm-box"><div class="nm-bh"><span>relations</span><output class="cx-ro nm-sub">{N.sub}</output></div><pre class="nm-rel">{N.rel}</pre></div>
              <div class="nm-box"><div class="nm-bh"><span>B = 1/n<sup>2</sup>, &Delta;B<sub>I</sub> = r<sub>Ij</sub>E<sub>j</sub> <Badge code="derived" pop="d:rform" /></span><output class="cx-ro nm-opt">{N.opt}</output></div><pre class="nm-db">{N.db}</pre></div>
            </div>
          </div>
          <output class="cx-ro nm-hov" aria-live="polite">{N.hov}</output>
          <div class="pf"><span class="nm-key"><b class="i">d15</b> independent</span><span class="nm-key"><b class="t">&minus;d22</b> tied</span><span class="nm-key"><b class="z">0</b> zero</span><span class="nm-key"><b class="tr">c12</b> transpose (index symmetry)</span><span class="nm-key"><b class="n">r11</b> allowed only under E</span><br>All operations off: every component independent. C3 on: most vanish, survivors pair up. Add one mirror: d keeps d15, d22, d31, d33. Then E along y: one mirror survives, the group reads m. Closure adds what the chosen elements imply (two mirrors give C3; C3 and one mirror give all three mirrors), drawn dashed. Under a field the matrix shows what crystal plus field allow; magnitudes are not computed. <Badge code="derived" pop="d:nm" /> <Badge code="derived" pop="d:curie" /></div>
        </figure>
        {/snippet}
        {#snippet visual()}
        <figure class="nm-v" data-pair="nm" bind:this={nmV}>
          <div class="nm-vart v-frame">
            <div class="nm-vst"><svg class="nm-st" viewBox="0 0 320 320" role="img" aria-label="Stereogram of the group in force, projected along c: mirror traces, threefold axis, orbit of a general direction, applied field">{@html N.st}</svg></div>
            <div class="nm-vgg"><svg class="nm-gg" viewBox="0 0 416 416" data-sweep data-nm-hover role="img" aria-label="Voigt matrix as glyphs: filled independent, outlined tied, dot zero">{@html N.gg}</svg></div>
          </div>
          <div class="nm-vside">
            <div class="nm-vbig">
              <div><span class="k">Group</span><span class="v nm-grp">{N.grp}</span></div>
              <div><span class="k">Independent</span><span class="v"><span class="nm-ind">{N.ind}</span><span class="sl">/</span><span class="nm-gen">{N.gen}</span></span></div>
            </div>
            <div class="v-ctl"><span class="v-lab">Property</span><div class="v-seg" role="group" aria-label="Property tensor">{#each KV as [k, l] (k)}<button type="button" data-nm-k={k} class:on={D.kind === k} aria-pressed={D.kind === k}>{l}</button>{/each}</div></div>
            <div class="v-ctl"><span class="v-lab">Symmetry operations</span><div class="v-seg" role="group" aria-label="Symmetry operations">{#each OV as [k, l] (k)}<button type="button" data-nm-op={k} class:on={D.ops[k]} aria-pressed={D.ops[k]}>{l}</button>{/each}</div></div>
            <div class="nm-vrow">
              <div class="v-ctl"><span class="v-lab">All operations</span><div class="v-seg" role="group" aria-label="Operation presets"><button type="button" data-nm-pre="none">Off</button><button type="button" data-nm-pre="all">On</button></div></div>
              <div class="v-ctl"><span class="v-lab">Static field</span><div class="v-seg" role="group" aria-label="Applied field direction">{#each FT as [k, l] (k)}<button type="button" data-nm-f={k} class:on={D.field === k} aria-pressed={D.field === k}>{k === "0" ? "None" : l}</button>{/each}</div></div>
            </div>
            <div class="nm-el" aria-live="polite">{@html N.el}</div>
            <output class="nm-hov" aria-live="polite">{N.hov}</output>
          </div>
          <div class="nm-vboxes">
            <div class="nm-box"><div class="nm-bh"><span>Relations</span><output class="nm-sub">{N.sub}</output></div><pre class="nm-rel">{N.rel}</pre></div>
            <div class="nm-box"><div class="nm-bh"><span>Induced &Delta;(1/n<sup>2</sup>) <Badge code="derived" pop="d:rform" /></span><output class="nm-opt">{N.opt}</output></div><pre class="nm-db">{N.db}</pre></div>
          </div>
          <p class="v-cap nm-vcap">Switch every operation off: all components light. Turn on the threefold axis: most go dark and the survivors pair up. Add one mirror: d keeps d15, d22, d31, d33. Then put the field along y: one mirror line survives and the group reads m. Filled: independent; outlined with a link to its partner: tied; dot: zero; small dashed: transpose; gold: allowed only under the field. Elements implied by closure are drawn dashed. The lobes repeat once per element of the group. <Badge code="derived" pop="d:nm" /> <Badge code="derived" pop="d:curie" /></p>
        </figure>
        {/snippet}
      </ModeVariant>
    </div>
  </section>

  <section class="lay" id="l2" data-pair="l2" data-spine="L2 Axes and allowed forms">
    <div class="sh"><h2 class="biref">L2 Axes and allowed forms</h2><span class="meta">IRE 1949 / IEEE 176-1987 axes; Weis & Gaylord 1985 Eqs. (2)-(19)</span></div>
    <div class="body">
      <p class="tx">Axes for tensors follow IRE 1949 / <span class="term" data-pop="g:ieee-176">IEEE 176-1987</span>, as used by Weis and Gaylord and by Volk and W&ouml;hlecke.</p>
      <div class="cx-tw">
        <table class="idx cx-t">
          <thead><tr><th>Axis</th><th>Rule</th><th class="r">Status</th></tr></thead>
          <tbody>
            <tr><td class="h">z</td><td>parallel to <i>c</i>, the threefold axis</td><td class="s"><Badge code="P" pop="r:weis1985|p. 195" /></td></tr>
            <tr><td class="h">x</td><td>along one of the equivalent <i>a</i> axes, perpendicular to a mirror plane; non-polar</td><td class="s"><Badge code="P" pop="r:weis1985|p. 195" /> <Badge code="P" pop="r:ieee176|Sec. 3.2.5, Table 5" /></td></tr>
            <tr><td class="h">y</td><td>completes a right-handed set; lies in a mirror plane</td><td class="s"><Badge code="P" pop="r:weis1985|p. 195" /></td></tr>
            <tr><td class="h"><span class="term" data-pop="g:plus-z-face">+z sense</span></td><td>the <i>c</i> face that becomes negative on compression; equivalently positive on cooling; third test: cleavage terracing</td><td class="s"><Badge code="P" pop="r:weis1985|pp. 192-193" /> <Badge code="P-comp" pop="r:volk2008|p. 2" /></td></tr>
            <tr><td class="h">+y sense</td><td>the <i>y</i> face that becomes negative on compression</td><td class="s"><Badge code="P" pop="r:weis1985|p. 195" /></td></tr>
            <tr><td class="h">IEEE 176-1987</td><td>+Z gives positive d<sub>33</sub>, +Y positive d<sub>22</sub></td><td class="s"><Badge code="P" pop="r:ieee176|Table 5 p. 18" /></td></tr>
          </tbody>
        </table>
      </div>

      <h3 class="h3">Which face is +z</h3>
      <ModeVariant>
        {#snippet tech()}
        <figure class="panel pz-t" data-pair="pz" bind:this={pzT}>
          <div class="ph"><span>One z-cut plate, three tests; face A up as drawn</span><span class="pz-gb"><button type="button" class="pz-b" data-pz="flip" data-drive aria-pressed="false" title="Turn the plate over">turn over</button><button type="button" class="pz-b" data-pz="reset" data-drive title="Undo all tests">reset</button></span></div>
          <div class="pz-cols">
            {#each PZT as [t, h, b] (t)}
            <div class="pz-col">
              <div class="pz-h"><span>{h}</span><button type="button" class="pz-b" data-pz={t} data-drive aria-pressed="false">{b}</button></div>
              <pre class="cx-ascii pz-a" data-t={t}>{Z[t].a}</pre>
              <output class="cx-ro pz-ro" data-t={t}>{Z[t].ro}</output>
              {#if t === "sq"}<p class="pz-rule">+z: the <i>c</i> face that becomes negative on compression <Badge code="P" pop="r:weis1985|pp. 192-193" />; +Z gives positive d<sub>33</sub> <Badge code="P" pop="r:ieee176|Table 5 p. 18" /></p>
              {:else if t === "cool"}<p class="pz-rule">+z: the <i>c</i> face that becomes positive on cooling; p<sub>3</sub> &lt; 0 <Badge code="P" pop="r:weis1985|p. 196, Eq. (2)" /></p>
              {:else}<p class="pz-rule">The &minus;<i>c</i> end of a domain etches much faster than the +<i>c</i> end <Badge code="P-comp" pop="r:volk2008|p. 168" /></p>{/if}
            </div>
            {/each}
          </div>
          <div class="pf">Compress, then cool, the same plate: face A turns negative, then positive, and both tests read +z = A. Compression pushes the cations toward their centred positions; cooling pulls them further out <Badge code="P" pop="r:weis1985|p. 193" />. Turn the plate over and every sign follows the polarization. Readout: sign of each face, then the +z face. <Badge code="derived" pop="d:pz" /></div>
        </figure>
        {/snippet}
        {#snippet visual()}
        <figure class="pz-v" data-pair="pz" bind:this={pzV}>
          <div class="pz-vrow">
            {#each PZV as [t, h, b] (t)}
            <div class="pz-vst" data-pz-st={t} data-on="0" data-flip="0">
              <div class="pz-vh"><h3>{h}</h3><button type="button" class="pz-vb" data-pz={t} data-drive aria-pressed="false">{b}</button></div>
              <div class="pz-vfig v-frame"><svg viewBox="0 0 300 260" role="img" aria-label="{h}: z-cut plate with its polarization arrow; face A on top, face B below">{@html Z[t].svg}</svg></div>
              <output class="pz-ro" data-t={t}>{Z[t].ro}</output>
              {#if t === "sq"}<p class="v-cap">The +<i>z</i> face is the <i>c</i> face that turns negative on compression <Badge code="P" pop="r:weis1985|pp. 192-193" />; +Z gives positive d<sub>33</sub> <Badge code="P" pop="r:ieee176|Table 5 p. 18" /></p>
              {:else if t === "cool"}<p class="v-cap">The +<i>z</i> face turns positive on cooling, since p<sub>3</sub> &lt; 0 <Badge code="P" pop="r:weis1985|p. 196, Eq. (2)" /></p>
              {:else}<p class="v-cap">The &minus;<i>c</i> end etches much faster than the +<i>c</i> end <Badge code="P-comp" pop="r:volk2008|p. 168" /></p>{/if}
            </div>
            {/each}
          </div>
          <div class="pz-vctl"><button type="button" class="pz-vb" data-pz="flip" data-drive aria-pressed="false">Turn the plate over</button><button type="button" class="pz-vb" data-pz="reset" data-drive>Reset</button></div>
          <p class="v-cap pz-vcap">Squeeze, then cool, the same plate: face A turns negative, then positive, and both tests name A as +<i>z</i>. Compression pushes the cations toward their centred positions; cooling pulls them further out <Badge code="P" pop="r:weis1985|p. 193" />. Turn the plate over and the charges follow the arrow. Signs only. <Badge code="derived" pop="d:pz" /></p>
        </figure>
        {/snippet}
      </ModeVariant>

      <h3 class="h3">Forms allowed in point group 3m</h3>
      <p class="tx"><span class="term" data-pop="g:voigt-notation">Voigt contraction</span> 11&rarr;1, 22&rarr;2, 33&rarr;3, 23&rarr;4, 13&rarr;5, 12&rarr;6.</p>
      <div class="cx-tw">
        <table class="idx cx-t">
          <thead><tr><th>Property</th><th class="r">Rank</th><th>Non-zero pattern</th><th class="r">Independent</th><th class="r">Computed</th><th class="r">Status</th></tr></thead>
          <tbody>
            <tr><td class="h"><span class="term" data-pop="g:pyroelectric-effect">Pyroelectric</span> p</td><td class="num">1</td><td>(0, 0, p<sub>3</sub>)</td><td class="num">1</td><td class="num">{C.pyro}</td><td class="s"><Badge code="P" pop="r:weis1985|Eq. (2)" /> <Badge code="derived" pop="d:forms" /></td></tr>
            <tr><td class="h">Permittivity</td><td class="num">2</td><td>diag(&epsilon;<sub>11</sub>, &epsilon;<sub>11</sub>, &epsilon;<sub>33</sub>)</td><td class="num">2</td><td class="num">{C.eps}</td><td class="s"><Badge code="P" pop="r:weis1985|Eq. (4)" /> <Badge code="derived" pop="d:forms" /></td></tr>
            <tr><td class="h">Any other symmetric rank-2 property (impermeability, thermal expansion, thermal conductivity)</td><td class="num">2</td><td>diag(t<sub>11</sub>, t<sub>11</sub>, t<sub>33</sub>)</td><td class="num">2</td><td class="num">{C.eps}</td><td class="s"><Badge code="derived" pop="d:nm" /></td></tr>
            <tr><td class="h"><span class="term" data-pop="g:piezoelectric-effect">Piezoelectric</span> d (3 &times; 6)</td><td class="num">3</td><td>d<sub>15</sub> = d<sub>24</sub>, d<sub>16</sub> = &minus;2d<sub>22</sub>, d<sub>21</sub> = &minus;d<sub>22</sub>, d<sub>31</sub> = d<sub>32</sub>, d<sub>33</sub></td><td class="num">4</td><td class="num">{C.d}</td><td class="s"><Badge code="P" pop="r:weis1985|Eq. (8)" /> <Badge code="derived" pop="d:forms" /></td></tr>
            <tr><td class="h"><span class="term" data-pop="g:eo-tensor">Linear electro-optic</span> r (6 &times; 3)</td><td class="num">3</td><td>r<sub>13</sub> = r<sub>23</sub>, r<sub>33</sub>, r<sub>22</sub> = &minus;r<sub>12</sub> = &minus;r<sub>61</sub>, r<sub>42</sub> = r<sub>51</sub></td><td class="num">4</td><td class="num">{C.r}</td><td class="s"><Badge code="P" pop="r:weis1985|Eq. (12)" /> <Badge code="derived" pop="d:forms" /></td></tr>
            <tr><td class="h"><span class="term" data-pop="g:elastic-stiffness">Elastic stiffness</span> c (6 &times; 6)</td><td class="num">4</td><td>c<sub>11</sub>, c<sub>12</sub>, c<sub>13</sub>, c<sub>14</sub>, c<sub>33</sub>, c<sub>44</sub>; c<sub>24</sub> = &minus;c<sub>14</sub>, c<sub>56</sub> = c<sub>14</sub>, c<sub>66</sub> = (c<sub>11</sub> &minus; c<sub>12</sub>)/2</td><td class="num">6</td><td class="num">{C.c}</td><td class="s"><Badge code="P" pop="r:weis1985|Eqs. (16)-(17)" /> <Badge code="derived" pop="d:forms" /></td></tr>
            <tr><td class="h">Elastic compliance s (6 &times; 6)</td><td class="num">4</td><td>as c, but s<sub>56</sub> = 2s<sub>14</sub>, s<sub>66</sub> = 2(s<sub>11</sub> &minus; s<sub>12</sub>)</td><td class="num">6</td><td class="num">{C.s}</td><td class="s"><Badge code="P" pop="r:weis1985|Eq. (16)" /> <Badge code="derived" pop="d:forms" /></td></tr>
            <tr><td class="h"><span class="term" data-pop="g:photoelastic-effect">Photoelastic</span> p (6 &times; 6)</td><td class="num">4</td><td>p<sub>11</sub>, p<sub>12</sub>, p<sub>13</sub>, p<sub>14</sub>, p<sub>31</sub>, p<sub>33</sub>, p<sub>41</sub>, p<sub>44</sub>; p<sub>42</sub> = &minus;p<sub>41</sub>, p<sub>24</sub> = &minus;p<sub>14</sub>, p<sub>56</sub> = p<sub>41</sub>, p<sub>65</sub> = p<sub>14</sub>, p<sub>66</sub> = (p<sub>11</sub> &minus; p<sub>12</sub>)/2</td><td class="num">8</td><td class="num">{C.p}</td><td class="s"><Badge code="P" pop="r:weis1985|Eq. (19)" /> <Badge code="derived" pop="d:forms" /></td></tr>
          </tbody>
        </table>
      </div>
      <p class="tx">The factors 2 in d<sub>16</sub>, s<sub>56</sub>, s<sub>66</sub> come from the contraction (engineering shear strain), not from the crystal <Badge code="P" pop="r:weis1985|pp. 199-200" /> <Badge code="derived" pop="d:voigt" />. Neumann's principle must be applied to the full tensor, then contracted <Badge code="P" pop="r:weis1985|p. 198" />.</p>

      <div class="cx-tw">
        <table class="idx cx-t">
          <thead><tr><th>Example of the result</th><th>Value</th><th class="r">Status</th></tr></thead>
          <tbody>
            <tr><td class="h">Optic axis</td><td><i>c</i>; <span class="term" data-pop="g:negative-uniaxial">negative uniaxial</span>: n<sub>o</sub> = 2.2866, n<sub>e</sub> = 2.2028 at 632.8 nm, 24.5 &deg;C, congruent</td><td class="s"><Badge code="P-comp" pop="r:weis1985|Table 2, orig. Nelson and Mikulyak 1974" /></td></tr>
            <tr><td class="h">Signs fixed by the axis rules</td><td>d<sub>22</sub> &gt; 0 and d<sub>33</sub> &gt; 0</td><td class="s"><Badge code="P" pop="r:weis1985|p. 198" /></td></tr>
          </tbody>
        </table>
      </div>
    </div>
  </section>

  <section class="lay" id="l3" data-pair="l3" data-spine="L3 Signs and broken symmetry">
    <div class="sh"><h2 class="biref">L3 Signs and broken symmetry</h2><span class="meta">non-polar x; residual sign freedom; Curie's principle under field</span></div>
    <div class="body">
      <p class="tx"><b>Why x is not polar.</b> <i>x</i> is perpendicular to a mirror plane, so any charge displaced on one side is mirrored on the other; the <i>x</i> faces cannot charge under stress <Badge code="P" pop="r:weis1985|p. 195" />. Practical orientation: in boules pulled along <i>z</i>, the mirror planes outcrop as three facets along the growth axis, 120&deg; apart, which mark <i>y</i> <Badge code="P-comp" pop="r:volk2008|p. 2" />.</p>
      <p class="tx"><b>Residual sign freedom.</b> A 180&deg; rotation about <i>z</i> keeps the axis rules for <i>z</i> but flips d<sub>22</sub>; once +<i>y</i> is fixed by d<sub>22</sub> &gt; 0 no freedom remains, so c<sub>14</sub> &gt; 0 in any frame that obeys IEEE 176 or IRE 1949 <Badge code="derived" pop="d:signs" />. A 180&deg; rotation about <i>x</i> flips <i>z</i> and therefore every odd-rank tensor (p, d, r, &chi;<sup>(2)</sup>) but not c or the photoelastic p <Badge code="derived" pop="d:signs" />.</p>
      <p class="tx"><b>Breaking the symmetry.</b> A static field is a polar vector, so the crystal under field keeps only the elements of 3m that leave the field unchanged (Curie's principle) <Badge code="derived" pop="d:curie" />. E along <i>z</i> keeps all of 3m: the crystal stays uniaxial and n<sub>o</sub>, n<sub>e</sub> shift through r<sub>13</sub> and r<sub>33</sub>. E along <i>y</i>, which lies in a mirror plane, keeps that one mirror: point symmetry m. E along <i>x</i>, which is perpendicular to a mirror plane, keeps no mirror (the mirror normal to <i>x</i> reverses E<sub>x</sub>; the other two mirror normals sit at 60&deg; and 120&deg; to <i>x</i>): point symmetry 1. For either transverse direction the impermeability acquires terms through r<sub>22</sub> and r<sub>51</sub> and a z-cut plate becomes biaxial <Badge code="derived" pop="d:curie" />: E<sub>x</sub> adds the xy term &minus;r<sub>22</sub>E<sub>x</sub>, which turns the in-plane principal axes to 45&deg;, and the xz term r<sub>51</sub>E<sub>x</sub>; E<sub>y</sub> splits the xx and yy terms by &mp;r<sub>22</sub>E<sub>y</sub> without turning them and adds the yz term r<sub>51</sub>E<sub>y</sub> <Badge code="derived" pop="d:rform" />. The Neumann machine shows this as the converse of Neumann's principle: lower the symmetry and new components appear.</p>
    </div>
  </section>
</CrystalSection>
